class Solution{
public:
    int box(vector<vector<int>>&matrix,int n,int m,int mid){
        int cnt=0;
        for(int i=0;i<n;i++){
             cnt += upper_bound(matrix[i].begin(), matrix[i].end(), mid) - matrix[i].begin();
        }
        return cnt;
    }
    int findMedian(vector<vector<int>>&matrix) {
      int low=INT_MAX,high=INT_MIN;
      int n=matrix.size();
      int m=matrix[0].size();
      for(int i=0;i<n;i++){
        low=min(low,matrix[i][0]);
        high=max(high,matrix[i][m-1]);
      }
      int req=(m*n/2);
      while(low<=high){
        int mid=low+(high-low)/2;
        int cnt=box(matrix,n,m,mid);
        if(cnt<=req){
            low=mid+1;
        }
        else high=mid-1;
      }
      return low;
    }
};
